#include <cassert>
#include <cstdio>
#include <fstream>
#include <vector>
#include "sm121_integer_core.h"
using qrt_q1_moe_hawkeye::Value;
using qrt_sm121_integer_core::Row;
std::vector<uint16_t> read(const char* path, size_t elements) {
    std::ifstream f(path, std::ios::binary | std::ios::ate);
    assert(f && size_t(f.tellg()) == elements * 2u);
    std::vector<uint16_t> values(elements);
    f.seekg(0); f.read(reinterpret_cast<char*>(values.data()), elements * 2u);
    assert(f); return values;
}
unsigned seed = 0x20260912u;
unsigned random_word() { seed ^= seed << 13; seed ^= seed >> 17; seed ^= seed << 5; return seed; }
int high(uint16_t v) { return v & 0x8000u ? int(v >> 8u) - 256 : int(v >> 8u); }
int main(int argc, char** argv) {
    assert(argc == 3);
    const auto q = read(argv[1], 7169u * 4096u), k = read(argv[2], 7169u * 512u);
    unsigned hist[17]{}, groups = 0, old_fast = 0, exceptions = 0, replays = 0, dominant = 0;
    for (unsigned sample = 0; sample < 16384u; ++sample) {
        const unsigned row = random_word() % 7169u, key = random_word() % (row + 1u), head = random_word() % 16u;
        Value carry{0u, -133, false};
        for (unsigned base = 0; base < 256u; base += 16u) {
            Row a{}, b{}; Value terms[17]; terms[0] = carry;
            for (unsigned i = 0; i < 16u; ++i) {
                a.original[i] = q[(row * 16u + head) * 256u + base + i];
                b.original[i] = k[(key * 2u + head / 8u) * 256u + base + i];
                terms[i + 1u] = qrt_q1_moe_hawkeye::multiply_bf16(a.original[i], b.original[i], -133);
            }
            qrt_sm121_integer_core::prepare(a); qrt_sm121_integer_core::prepare(b);
            int32_t parts[4]{}; uint32_t at[4]{}, bt[4]{}; int am, bm;
            const int au = qrt_sm121_integer_parts::row_unit_range(a.original, &am);
            const int bu = qrt_sm121_integer_parts::row_unit_range(b.original, &bm);
            for (unsigned i = 0; i < 16u; ++i) {
                const auto x = qrt_sm121_integer_core::encode(a.original[i], a.unit);
                const auto y = qrt_sm121_integer_core::encode(b.original[i], b.unit);
                parts[0] += high(x) * high(y); parts[1] += high(x) * int(y & 255u);
                parts[2] += int(x & 255u) * high(y); parts[3] += int(x & 255u) * int(y & 255u);
                at[i / 4u] |= qrt_sm121_integer_parts::trailing_bits(qrt_sm121_integer_parts::encode(a.original[i], au)) << ((i % 4u) * 8u);
                bt[i / 4u] |= qrt_sm121_integer_parts::trailing_bits(qrt_sm121_integer_parts::encode(b.original[i], bu)) << ((i % 4u) * 8u);
            }
            qrt_sm121_group16::AlignedSum diagnostic{}, actual{}; const int32_t zeros[4]{};
            old_fast += qrt_sm121_integer_parts::sum_exact_range(carry, zeros, au, am, bu, bm, &diagnostic, at, bt);
            unsigned pairs = 99u;
            assert(qrt_sm121_integer_core::sum(carry, a, b, parts, &actual, &pairs));
            const Value scaled{actual.value.magnitude, int16_t(actual.max_exponent - 2), actual.value.negative};
            const auto result = qrt_sm121_group16::finish_accumulator(qrt_q1_moe_hawkeye::group_sum<26,-133>(&scaled, 1u));
            const auto expected = qrt_sm121_group16::finish_accumulator(qrt_q1_moe_hawkeye::group_sum<26,-133>(terms, 17u));
            assert(result.significand == expected.significand && result.exponent == expected.exponent && result.negative == expected.negative);
            ++groups; ++hist[pairs]; replays += pairs; exceptions += bool(a.exceptions | b.exceptions);
            dominant += carry.exponent >= am + bm - 254; carry = expected;
        }
    }
    std::printf("{\"kind\":\"original_qk_sparse_core_coverage\",\"groups\":%u,\"old_zero_replay_groups\":%u,\"core_zero_replay_groups\":%u,\"encoded_exception_groups\":%u,\"carry_dominant_groups\":%u,\"replayed_pairs\":%u,\"canonical_mismatches\":0,\"replay_histogram\":[", groups, old_fast, hist[0], exceptions, dominant, replays);
    for (unsigned i = 0u; i <= 16u; ++i) std::printf("%s%u", i ? "," : "", hist[i]);
    std::puts("],\"inference_or_performance_acceptance\":false}");
}

